def VTask.memPartition {α : Type u_1} (f : ℕ → Set α) (n : ℕ) : Set (Set α) :=
match n with
| 0 => { univ }
| n + 1 =>
  let prev_partition := VTask.memPartition f n;
  let rec splitPartition (prev_sets : Set (Set α)) : Set (Set α) :=
    match prev_sets with
    | {} => {}
    | s :: ss =>
      let s_intersect_fn := s ∩ f n;
      let s_diff_fn := s \ f n;
      insert s_intersect_fn (insert s_diff_fn (splitPartition ss))
  splitPartition prev_partition
